-- Dolce Vita Supabase backend. Run once in Dashboard > SQL Editor.
create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','staff','admin');
create type public.account_status as enum ('pending','active','inactive');
create type public.appointment_status as enum ('pending','confirmed','completed','rejected','cancelled');
create type public.inquiry_status as enum ('open','responded','closed');
create type public.payment_method as enum ('cash','gcash','card','bank_transfer');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, first_name text not null, last_name text not null, name text not null, email text not null unique, phone_number text, address text, role public.user_role not null default 'customer', status public.account_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.service_categories (id bigint generated always as identity primary key, name text not null unique, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.services (id bigint generated always as identity primary key, category_id bigint not null references public.service_categories(id), name text not null, description text not null, price numeric(10,2) not null check(price>=0), duration_minutes integer not null check(duration_minutes>0), is_active boolean not null default true, is_available boolean not null default true, image text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.appointments (id bigint generated always as identity primary key, booking_reference text not null unique, customer_id uuid not null references public.profiles(id), appointment_date date not null, start_time time not null, estimated_total numeric(10,2) not null, estimated_duration_minutes integer not null, status public.appointment_status not null default 'pending', contact_number text not null, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.appointment_items (id bigint generated always as identity primary key, appointment_id bigint not null references public.appointments(id) on delete cascade, service_id bigint not null references public.services(id), service_name text not null, unit_price numeric(10,2) not null, duration_minutes integer not null, line_total numeric(10,2) not null);
create table public.appointment_status_history (id bigint generated always as identity primary key, appointment_id bigint not null references public.appointments(id) on delete cascade, status public.appointment_status not null, changed_by uuid references public.profiles(id), notes text, created_at timestamptz not null default now());
create table public.sales (id bigint generated always as identity primary key, appointment_id bigint not null unique references public.appointments(id), actual_total numeric(10,2) not null, payment_method public.payment_method not null default 'cash', receipt_number text, collected_by uuid not null references public.profiles(id), collected_at timestamptz not null default now());
create table public.customer_inquiries (id bigint generated always as identity primary key, customer_id uuid not null references public.profiles(id), assigned_to uuid references public.profiles(id), status public.inquiry_status not null default 'open', is_critical boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_inquiry_messages (id bigint generated always as identity primary key, inquiry_id bigint not null references public.customer_inquiries(id) on delete cascade, sender_id uuid references public.profiles(id) on delete set null, sender_role public.user_role not null, message text not null, created_at timestamptz not null default now());

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and status='active')$$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role in ('staff','admin') and status='active')$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare r public.user_role:=case when new.raw_user_meta_data->>'account_type'='staff' then 'staff' else 'customer' end; begin insert into public.profiles(id,first_name,last_name,name,email,phone_number,address,role,status) values(new.id,coalesce(new.raw_user_meta_data->>'first_name',''),coalesce(new.raw_user_meta_data->>'last_name',''),trim(concat_ws(' ',new.raw_user_meta_data->>'first_name',new.raw_user_meta_data->>'last_name')),new.email,new.raw_user_meta_data->>'phone_number',new.raw_user_meta_data->>'address',r,case when r='staff' then 'pending' else 'active' end); return new; end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

alter table public.profiles enable row level security; alter table public.service_categories enable row level security; alter table public.services enable row level security; alter table public.appointments enable row level security; alter table public.appointment_items enable row level security; alter table public.appointment_status_history enable row level security; alter table public.sales enable row level security; alter table public.customer_inquiries enable row level security; alter table public.customer_inquiry_messages enable row level security;
create policy "profile read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_staff()); create policy "admin profile update" on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "category read" on public.service_categories for select using(is_active or public.is_staff()); create policy "admin category" on public.service_categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "service read" on public.services for select using((is_active and is_available) or public.is_staff()); create policy "admin service" on public.services for all to authenticated using(public.is_admin()) with check(public.is_admin());

create or replace function public.public_catalogue() returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('categories',coalesce((select jsonb_agg(to_jsonb(c) order by c.name) from public.service_categories c where c.is_active),'[]'),'services',coalesce((select jsonb_agg(to_jsonb(s) order by s.name) from public.services s join public.service_categories c on c.id=s.category_id where s.is_active and s.is_available and c.is_active),'[]'))$$;
create or replace function public.app_bootstrap() returns jsonb language plpgsql security definer set search_path=public as $$declare p public.profiles; begin select * into p from public.profiles where id=auth.uid(); if p.id is null or p.status<>'active' then raise exception 'Your account is not active.'; end if; return jsonb_build_object('user',to_jsonb(p),'users',case when p.role in('staff','admin') then coalesce((select jsonb_agg(to_jsonb(x)) from public.profiles x),'[]') else jsonb_build_array(to_jsonb(p)) end,'categories',coalesce((select jsonb_agg(to_jsonb(c)) from public.service_categories c),'[]'),'services',coalesce((select jsonb_agg(to_jsonb(s)) from public.services s),'[]'),'appointments',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(ai)) from public.appointment_items ai where ai.appointment_id=a.id),'[]'))) from public.appointments a where p.role<>'customer' or a.customer_id=p.id),'[]'),'inquiries',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('messages',coalesce((select jsonb_agg(to_jsonb(m) order by m.created_at) from public.customer_inquiry_messages m where m.inquiry_id=i.id),'[]')) order by i.updated_at desc) from public.customer_inquiries i where p.role<>'customer' or i.customer_id=p.id),'[]'),'sales',case when p.role='admin' then coalesce((select jsonb_agg(to_jsonb(s)) from public.sales s),'[]') else '[]'::jsonb end); end$$;
create or replace function public.create_appointment(request jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare a bigint; total numeric:=0; duration integer:=0; s public.services; service_id bigint; begin for service_id in select jsonb_array_elements_text(request->'service_ids')::bigint loop select * into s from public.services where id=service_id and is_active and is_available; if s.id is null then raise exception 'A selected service is unavailable.'; end if; total:=total+s.price; duration:=duration+s.duration_minutes; end loop; if duration=0 then raise exception 'Select at least one service.'; end if; if exists(select 1 from public.appointments where appointment_date=(request->>'appointment_date')::date and start_time=(request->>'start_time')::time and status in('pending','confirmed')) then raise exception 'That time slot is no longer available.'; end if; insert into public.appointments(booking_reference,customer_id,appointment_date,start_time,estimated_total,estimated_duration_minutes,contact_number,notes) values('DV-'||to_char(now(),'YYMMDD')||'-'||substr(gen_random_uuid()::text,1,6),auth.uid(),(request->>'appointment_date')::date,(request->>'start_time')::time,total,duration,request->>'contact_number',nullif(request->>'notes','')) returning id into a; for service_id in select jsonb_array_elements_text(request->'service_ids')::bigint loop select * into s from public.services where id=service_id; insert into public.appointment_items(appointment_id,service_id,service_name,unit_price,duration_minutes,line_total) values(a,s.id,s.name,s.price,s.duration_minutes,s.price); end loop; return jsonb_build_object('appointment_id',a,'message','Appointment requested.'); end$$;
create or replace function public.create_inquiry(body text, critical boolean default true) returns jsonb language plpgsql security definer set search_path=public as $$declare i bigint; begin if trim(coalesce(body,''))='' then raise exception 'A message is required.'; end if; insert into public.customer_inquiries(customer_id,is_critical) values(auth.uid(),critical) returning id into i; insert into public.customer_inquiry_messages(inquiry_id,sender_id,sender_role,message) values(i,auth.uid(),'customer',trim(body)); return jsonb_build_object('id',i,'message','Inquiry created.'); end$$;
create or replace function public.customer_inquiry_message(inquiry bigint, body text) returns jsonb language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from public.customer_inquiries where id=inquiry and customer_id=auth.uid()) then raise exception 'Conversation not found.'; end if; insert into public.customer_inquiry_messages(inquiry_id,sender_id,sender_role,message) values(inquiry,auth.uid(),'customer',trim(body)); update public.customer_inquiries set status='open',updated_at=now() where id=inquiry; return jsonb_build_object('message','Message sent.'); end$$;
create or replace function public.staff_inquiry_message(inquiry bigint, body text, next_status public.inquiry_status default 'responded') returns jsonb language plpgsql security definer set search_path=public as $$begin if not public.is_staff() then raise exception 'Staff access is required.'; end if; insert into public.customer_inquiry_messages(inquiry_id,sender_id,sender_role,message) values(inquiry,auth.uid(),(select role from public.profiles where id=auth.uid()),trim(body)); update public.customer_inquiries set assigned_to=auth.uid(),status=next_status,updated_at=now() where id=inquiry; return jsonb_build_object('message','Response sent.'); end$$;
create or replace function public.staff_update_appointment(appointment bigint, update_data jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare state public.appointment_status:=(update_data->>'status')::public.appointment_status; begin if not public.is_staff() then raise exception 'Staff access is required.'; end if; update public.appointments set status=state,updated_at=now() where id=appointment; insert into public.appointment_status_history(appointment_id,status,changed_by,notes) values(appointment,state,auth.uid(),'Updated by staff'); if state='completed' then insert into public.sales(appointment_id,actual_total,payment_method,receipt_number,collected_by) values(appointment,(update_data->>'actual_total')::numeric,coalesce((update_data->>'payment_method')::public.payment_method,'cash'),nullif(update_data->>'receipt_number',''),auth.uid()) on conflict(appointment_id) do update set actual_total=excluded.actual_total,payment_method=excluded.payment_method,receipt_number=excluded.receipt_number,collected_by=excluded.collected_by,collected_at=now(); end if; return jsonb_build_object('message',case when state='completed' then 'Appointment completed and sale saved.' else 'Appointment status updated.' end); end$$;
create or replace function public.approve_staff(staff_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'Administrator access is required.'; end if; update public.profiles set status='active',updated_at=now() where id=staff_id and role='staff'; return jsonb_build_object('message','Staff account approved.'); end$$;
grant execute on function public.public_catalogue() to anon,authenticated; grant execute on function public.app_bootstrap(),public.create_appointment(jsonb) to authenticated;
grant execute on function public.create_inquiry(text,boolean),public.customer_inquiry_message(bigint,text),public.staff_inquiry_message(bigint,text,public.inquiry_status),public.staff_update_appointment(bigint,jsonb),public.approve_staff(uuid) to authenticated;

insert into storage.buckets(id,name,public) values('service-images','service-images',true) on conflict(id) do update set public=true;
create policy "service image read" on storage.objects for select using(bucket_id='service-images'); create policy "admin image upload" on storage.objects for insert to authenticated with check(bucket_id='service-images' and public.is_admin());
